using System;using System.Collections.Generic;using System.Diagnostics;using System.Globalization;using System.IO;using System.Linq;using System.Text;using System.Threading.Tasks;using System.Web.Script.Serialization;
namespace Iris {
    public sealed class SteamProgressClient : IDisposable {
        readonly object gate=new object();readonly bool qa;Process process;SteamCounterReply latest=new SteamCounterReply();DateTime attempted;bool disposed;string key="";
        public SteamProgressClient(bool qa=false){this.qa=qa;}
        internal static SteamCounterReply RetainSteamSamples(SteamCounterReply previous,SteamCounterReply incoming){
            var samples=incoming.Items.Where(sample=>sample!=null).ToList();
            foreach(var sample in previous.Items){
                if(samples.Count>=8)break;
                if(sample.Id!=null&&sample.Id.StartsWith("steam:",StringComparison.Ordinal)&&!samples.Any(next=>next.Id==sample.Id))
                    samples.Add(sample);
            }
            return new SteamCounterReply{Items=samples.ToArray()};
        }
        static string ReadLine(StreamReader input){var text=new StringBuilder();int value;while((value=input.Read())>=0&&value!='\n'){if(text.Length>=32768)throw new InvalidDataException();if(value!='\r')text.Append((char)value);}return value<0&&text.Length==0?null:text.ToString();}
        public void Configure(IEnumerable<ActiveDownload> active){var targets=active.Where(i=>i.Source=="Steam"||i.Id==ChromeDownloadCounter.TargetId&&i.ChromeCounterEligible).Select(i=>new SteamCounterTarget{Id=i.Id,Name=i.Name}).Take(8).ToArray();string next=string.Join("|",targets.Select(t=>t.Id+":"+t.Name));lock(gate){if(disposed)return;if(targets.Length==0){Stop();key="";return;}if(process!=null&&process.HasExited){process.Dispose();process=null;latest=new SteamCounterReply();}if(process==null){if(DateTime.UtcNow-attempted<TimeSpan.FromSeconds(10))return;attempted=DateTime.UtcNow;string binary=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"Iris.SteamProgressHost.exe");if(!File.Exists(binary))return;try{var owned=process=Process.Start(new ProcessStartInfo(binary,qa?"--qa":""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden,RedirectStandardInput=true,RedirectStandardOutput=true,StandardOutputEncoding=Encoding.UTF8});Task.Factory.StartNew(delegate{try{var reader=owned.StandardOutput;string line;while((line=ReadLine(reader))!=null){var reply=new JavaScriptSerializer{MaxJsonLength=32768}.Deserialize<SteamCounterReply>(line);if(reply==null||reply.Items==null||reply.Items.Length>8)continue;lock(gate)if(process==owned&&!disposed)latest=RetainSteamSamples(latest,reply);}}catch{}});key="";}catch{process=null;return;}}if(next!=key)try{latest=new SteamCounterReply();process.StandardInput.WriteLine(new JavaScriptSerializer().Serialize(new SteamCounterRequest{Items=targets}));process.StandardInput.Flush();key=next;}catch{Stop();}}}
        public ActiveDownload[] Merge(ActiveDownload[] values,DateTime now){lock(gate){var result=new List<ActiveDownload>();foreach(var item in values){bool chrome=item.Id==ChromeDownloadCounter.TargetId;if(chrome&&!item.ChromeCounterEligible){result.Add(item);continue;}if(item.CurrentCounter&&item.Total>0&&!item.Rounded){result.Add(item);continue;}var sample=latest.Items.FirstOrDefault(v=>v.Id==item.Id);DateTime at;if(sample==null||!DateTime.TryParse(sample.At,CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out at)||at>now.AddSeconds(2)||now-at>TimeSpan.FromSeconds(4)||sample.Fraction.HasValue&&(double.IsNaN(sample.Fraction.Value)||sample.Fraction<0||sample.Fraction>=1)){result.Add(item);continue;}bool bytes=sample.Total>0&&sample.Total<=1e16&&sample.Received>=0&&sample.Received<sample.Total&&!double.IsNaN(sample.Total)&&!double.IsNaN(sample.Received);if(!bytes&&!sample.Fraction.HasValue){result.Add(item);continue;}result.Add(new ActiveDownload{Id=item.Id,Name=item.Name,Source=chrome?"Chrome":"Steam",Received=bytes?sample.Received:0,Total=bytes?sample.Total:-1,ReportedFraction=sample.Fraction,Rounded=sample.Rounded,CounterUtc=at,FreshForSeconds=4,ActivitySeconds=chrome?item.ActivitySeconds:75,Utc=item.Utc,CounterOrigin=chrome?"Chrome-Downloadansicht":L.T("Steam-Oberfläche"),ProgressNote=item.ProgressNote});}return result.ToArray();}}
        void Stop(){var owned=process;process=null;latest=new SteamCounterReply();if(owned!=null){try{owned.StandardInput.WriteLine("{\"Stop\":true}");owned.StandardInput.Flush();owned.StandardInput.Close();}catch{}Task.Factory.StartNew(delegate{try{owned.WaitForExit(6000);}catch{}finally{owned.Dispose();}});}}
        public void Dispose(){lock(gate){disposed=true;Stop();}}
    }
}
